CREATE TABLE IF NOT EXISTS results (match_id TEXT NOT NULL, entry_id INTEGER NOT NULL, slot INTEGER NOT NULL, song_key TEXT NOT NULL DEFAULT '', dx INTEGER, dx_max INTEGER, ach INTEGER, image TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', reason TEXT NOT NULL DEFAULT '', submitted_at TEXT NOT NULL DEFAULT (datetime('now')), reviewed_at TEXT, reviewer TEXT NOT NULL DEFAULT '', ver TEXT NOT NULL DEFAULT '', PRIMARY KEY (match_id, entry_id, slot));
